/**
 * Canonical expense type classification for the expense ledger. This is the
 * single definition used by the backend enum layer (re-export shim),
 * the `expense_type` PostgreSQL enum registration, GraphQL Pothos
 * registration, and frontend consumers.
 */
export enum ExpenseType {
  /** Auto-generated by the carryover settlement flow; never manually creatable. */
  SALARIES = "Salaries",
  MARKETING = "Marketing",
  LOGISTICS = "Logistics",
  TECHNOLOGY = "Technology",
}
